                color = row[c - 1]
                if color and row[c] == 0 and row[c + 1] == color:
                    out[r][c] = color

    if not bars:
        return out

    # Vertical stems below the lowest bar determine the columns to extend.
    lowest = max(bars)
    stem_cols = {}
    for c in range(w):
        vals = [grid[r][c] for r in range(lowest + 1, h) if grid[r][c]]
        if vals:
            stem_cols[c] = vals[-1]

    # Extend each stem upward. Between bars, use the color of the next
    # horizontal bar below; below the final bar, retain the stem's color.
    for c, stem_color in stem_cols.items():
        for r in range(h):
            below = [br for br in bars if br >= r]
            if below:
                br = min(below)
                color = out[br][c]
                if color:
                    out[r][c] = color
            else:
                out[r][c] = stem_color

