def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    gaps = {}

    # Find horizontal one-cell gaps.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                gaps.setdefault(c, []).append((r, color))

    # Extend each gap upward, stopping at another gap or existing object.
    for c, events in gaps.items():
        events.sort()
        event_rows = {r for r, _ in events}
        for r, color in events:
            rr = r - 1
            while rr >= 0 and grid[rr][c] == 0 and rr not in event_rows:
                out[rr][c] = color
                rr -= 1

    # The vertical strokes below the horizontal bars extend upward to the
    # lowest horizontal bar, without crossing it.
    bar_rows = []
    for r in range(h):
        if sum(v != 0 for v in grid[r]) >= 3:
            bar_rows.append(r)

    if bar_rows:
        lowest_bar = max(bar_rows)
        for c in range(w):
            seeds = [r for r in range(lowest_bar + 1, h) if grid[r][c] != 0]
            if seeds:
                color = grid[seeds[0]][c]
                for rr in range(lowest_bar + 1, min(seeds) + 1):
                    if out[rr][c] == 0:
                        out[rr][c] = color

    return out
